package cn.pojuzhiyuan.captain;
import android.content.Context;
import android.app.AlertDialog;
import android.graphics.*;
import android.view.*;
import org.json.*;
import java.net.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

/** Native tile canvas, existing event overlays, pan/zoom and read-only details. */
public final class SandMapView extends View {
    private double lat,lon;private int zoom,min=1,max=18;private final String base,token,event;private JSONArray marks;private boolean available;private String revision="";private volatile int sourceGeneration=0;
    private final ExecutorService fetch=Executors.newFixedThreadPool(4);private final Map<String,Tile> cache=Collections.synchronizedMap(new LinkedHashMap<String,Tile>(256,.75f,true){protected boolean removeEldestEntry(Map.Entry<String,Tile> e){return size()>240;}});private final Set<String> inflight=Collections.synchronizedSet(new HashSet<>());private final Paint paint=new Paint(3);private volatile boolean disposed=false;private float downX,downY,lastX,lastY;private boolean moved;private final ScaleGestureDetector scale;
    private static final class Tile{Bitmap image;int actual;Tile(Bitmap b,int z){image=b;actual=z;}}
    public SandMapView(Context c,String base,String token,String event,JSONObject scene)throws JSONException{
        super(c);this.base=base;this.token=token;this.event=event;marks=scene.getJSONArray("marks");JSONArray center=scene.optJSONArray("center");lat=center==null?0:center.getDouble(0);lon=center==null?0:center.getDouble(1);min=scene.optInt("min_zoom",1);max=scene.optInt("max_zoom",18);zoom=Math.max(min,Math.min(max,scene.optInt("zoom",13)));available=scene.optBoolean("map_available");revision=scene.optString("map_revision");setContentDescription("当前火情沙盘，可拖动、双指缩放并点击标记查看详情");scale=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){if(d.getScaleFactor()>1.08f){zoom(1);return true;}if(d.getScaleFactor()<.92f){zoom(-1);return true;}return false;}});
    }
    public void dispose(){disposed=true;fetch.shutdownNow();cache.clear();}
    public void update(JSONObject scene)throws JSONException{String next=scene.optString("map_revision");if(!next.equals(revision)){cache.clear();sourceGeneration++;revision=next;}marks=scene.getJSONArray("marks");available=scene.optBoolean("map_available");min=scene.optInt("min_zoom",1);max=scene.optInt("max_zoom",18);zoom=Math.max(min,Math.min(max,zoom));invalidate();}
    public void retry(){synchronized(cache){cache.entrySet().removeIf(e->e.getValue().image==null);}invalidate();}
    public void zoom(int change){zoom=Math.max(min,Math.min(max,zoom+change));invalidate();}
    private void load(String key,int z,int x,int y){if(disposed||inflight.size()>24||!inflight.add(key))return;final int generation=sourceGeneration;fetch.execute(()->{HttpURLConnection c=null;Tile tile=new Tile(null,z);try{c=(HttpURLConnection)new URL(base+"/app/v2/tile?event_id="+URLEncoder.encode(event,"UTF-8")+"&z="+z+"&x="+x+"&y="+y).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(7000);c.setReadTimeout(10000);c.setRequestProperty("Authorization","Bearer "+token);if(c.getResponseCode()==200){String type=c.getContentType();if(type!=null&&type.startsWith("image/")){ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>1024*1024)throw new IOException();out.write(bytes,0,n);}}byte[] bytes=out.toByteArray();BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth<=2048&&options.outHeight<=2048){options.inJustDecodeBounds=false;options.inSampleSize=1;while(options.outWidth/options.inSampleSize>256||options.outHeight/options.inSampleSize>256)options.inSampleSize*=2;tile.image=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);String actual=c.getHeaderField("X-Map-Zoom");tile.actual=actual==null?z:Integer.parseInt(actual);if(tile.actual<0||tile.actual>z||z-tile.actual>4)tile.image=null;}}}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();if(!disposed&&generation==sourceGeneration)cache.put(key,tile);inflight.remove(key);if(!disposed)postInvalidate();}});}
    private float density(){return getResources().getDisplayMetrics().density;}
    private float viewWidth(){return getWidth()/density();}
    private float viewHeight(){return getHeight()/density();}
    @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.scale(density(),density());canvas.drawColor(0xffd9e8ed);double centerX=MapMath.x(lon,zoom),centerY=MapMath.y(lat,zoom);int firstX=(int)Math.floor((centerX-viewWidth()/2.)/256),firstY=(int)Math.floor((centerY-viewHeight()/2.)/256);int cols=(int)viewWidth()/256+3,rows=(int)viewHeight()/256+3;
        for(int dx=0;dx<cols;dx++)for(int dy=0;dy<rows;dy++){int x=firstX+dx,y=firstY+dy;if(x<0||y<0||x>=1<<zoom||y>=1<<zoom)continue;String key=zoom+"/"+x+"/"+y;Tile t=cache.get(key);float left=(float)(x*256-centerX+viewWidth()/2.),top=(float)(y*256-centerY+viewHeight()/2.);RectF dst=new RectF(left,top,left+256,top+256);if(t!=null&&t.image!=null){int factor=1<<(zoom-t.actual),w=t.image.getWidth(),h=t.image.getHeight();Rect src=new Rect((x%factor)*w/factor,(y%factor)*h/factor,(x%factor+1)*w/factor,(y%factor+1)*h/factor);canvas.drawBitmap(t.image,src,dst,paint);}else{paint.setColor(0xffb6cdd5);paint.setStyle(Paint.Style.STROKE);canvas.drawRect(dst,paint);paint.setStyle(Paint.Style.FILL);if(t==null&&available)load(key,zoom,x,y);}}
        for(int i=0;i<marks.length();i++)try{JSONObject m=marks.getJSONObject(i);JSONArray points=m.getJSONArray("points");Path path=new Path();float px=0,py=0;for(int j=0;j<points.length();j++){JSONArray p=points.getJSONArray(j);px=(float)(MapMath.x(p.getDouble(1),zoom)-centerX+viewWidth()/2.);py=(float)(MapMath.y(p.getDouble(0),zoom)-centerY+viewHeight()/2.);if(j==0)path.moveTo(px,py);else path.lineTo(px,py);}paint.setColor(Color.parseColor(m.optString("color","#1769d2")));paint.setStrokeWidth(2);paint.setStyle(Paint.Style.STROKE);if(points.length()>1){if(m.optString("geometry").equals("polygon"))path.close();canvas.drawPath(path,paint);}paint.setStyle(Paint.Style.FILL);canvas.drawCircle(px,py,5,paint);paint.setTextSize(12);paint.setColor(Color.WHITE);paint.setStrokeWidth(2);paint.setStyle(Paint.Style.STROKE);String title=m.optString("title");if(title.length()>14)title=title.substring(0,14);canvas.drawText(title,px+7,py,paint);paint.setStyle(Paint.Style.FILL);paint.setColor(0xff163c4e);canvas.drawText(title,px+7,py,paint);}catch(Exception ignored){}
        boolean shown=false,failed=false;synchronized(cache){for(Tile t:cache.values()){shown|=t.image!=null;failed|=t.image==null;}}
        paint.setStyle(Paint.Style.FILL);paint.setColor(0xddffffff);canvas.drawRect(0,0,viewWidth(),22,paint);paint.setColor(0xff163c4e);paint.setTextSize(10);String notice=!available?"本地底图未接入":!shown?(inflight.isEmpty()&&failed?"底图未加载，点击顶部菜单重试":"正在加载本地影像…"):"已登记态势 · 待核实  |  级别 "+zoom;canvas.drawText(notice,10,15,paint);
    }
    @Override public boolean onTouchEvent(MotionEvent e){scale.onTouchEvent(e);float x=e.getX()/density(),y=e.getY()/density();if(e.getActionMasked()==MotionEvent.ACTION_DOWN){getParent().requestDisallowInterceptTouchEvent(true);downX=lastX=x;downY=lastY=y;moved=false;return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){if(Math.abs(x-downX)+Math.abs(y-downY)>12)moved=true;if(!scale.isInProgress()&&e.getPointerCount()==1){lon=MapMath.lon(MapMath.x(lon,zoom)-(x-lastX),zoom);lat=MapMath.lat(MapMath.y(lat,zoom)-(y-lastY),zoom);lon=Math.max(-180,Math.min(180,lon));lat=Math.max(-85,Math.min(85,lat));invalidate();}lastX=x;lastY=y;return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP){getParent().requestDisallowInterceptTouchEvent(false);if(!moved)details(x,y);return true;}return true;}
    private void details(float x,float y){double best=24;JSONObject selected=null;for(int i=0;i<marks.length();i++)try{JSONObject m=marks.getJSONObject(i);JSONArray points=m.getJSONArray("points");for(int j=0;j<points.length();j++){JSONArray p=points.getJSONArray(j);double dx=MapMath.x(p.getDouble(1),zoom)-MapMath.x(lon,zoom)+viewWidth()/2.-x,dy=MapMath.y(p.getDouble(0),zoom)-MapMath.y(lat,zoom)+viewHeight()/2.-y,d=Math.hypot(dx,dy);if(d<best){best=d;selected=m;}}}catch(Exception ignored){}if(selected!=null)new AlertDialog.Builder(getContext()).setTitle(selected.optString("title")).setMessage(selected.optString("detail")+"\n"+selected.optString("status")+"\n来源："+selected.optString("source")).setPositiveButton("关闭",null).show();}
}
